var t=[{title:`Wat de vorm verandert`,text:`Bij sommige lifts kan het hangende gewicht rond je pols of onderarm bewegen, en het balanceert anders dan een dumbbell. Goblet squats, deadlifts en carries gebruiken de bel op vrij eenvoudige manieren. Cleans, snatches en andere ballistische vaardigheden voegen momentum en coördinatie-eisen toe die voor beginners te veel kunnen zijn.`},{title:`Begin met de basis`,text:`Leer een beheerste heupscharnier en een eenvoudige deadlift voordat je een swing probeert, en doe goblet squats, deadlifts, rows of carries voor ballistisch werk met veel coördinatie. Kies een kettlebell die licht genoeg is voor herhaalde stabiele bewegingen maar zwaar genoeg om je uit te dagen. Geslacht of leeftijd alleen zeggen niet wat het juiste startgewicht is; je kracht, ervaring en de oefening die je kiest tellen.`},{title:`Mechaniek van de swing`,text:`Bij een gebruikelijke tweehandige swing gaat de bel van tussen je benen naar ongeveer borsthoogte, aangedreven door een krachtige heupextensie en niet door je armen op te tillen. Houd je wervelkolom beheerst, laat je knieën een beetje buigen en leid de bel elke keer langs dezelfde boog. Maak van de oefening geen diepe squat met een front raise.`},{title:`Veiligheid en opbouw`,text:`Oefen wanneer de vloer, je handen en de omgeving vrij en droog zijn. Laat genoeg ruimte voor en achter je voor het pad van de bel. Stop wanneer je grip of scharniertechniek begint te verslappen. Ga pas van deadlifts en beheerste hinges naar korte sets swings wanneer je de beweging betrouwbaar kunt uitvoeren.`},{title:`TrainUp gebruiken`,text:`Stel je vloeroppervlak, plafondhoogte en ondergrond nauwkeurig in bij Profiel. Je schema kiest alleen oefeningen die passen bij je ruimte, ondergrond, beperkingen en coördinatie, wat telt voor zwaaiende bewegingen in een kleine kamer.`}];var i=[{label:`ACE: techniek van de tweehandige kettlebellswing`,url:`https://www.acefitness.org/continuing-education/certified/january-2025/8788/the-ace-do-it-better-series-the-two-handed-kettlebell-swing/`},{label:`ACE-oefeningenbibliotheek`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Mayo Clinic: techniek bij krachttraining (2026)`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`}];var a={sections:t,sources:i};export{a as default,t as sections,i as sources};